define({"topics":[{"title":"Electrical Safety - Global Operator Cabinet (GOC)","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_GOC_2.html","attributes":{"data-id":"id_2013526"},"menu":{"hasChildren":false},"tocID":"id_2013526-d46e220863","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_68.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e220967","topics":[]},{"title":"Applying LOTO - Global Operator Cabinet (GOC) and operator workspace","shortdesc":"<p class=\"shortdesc\">Apply LOTO before servicing the GOC or items in the operator workspace. Applying LOTO makes sure the environment is safe when working on these items.<\/p>","href":"t_Applying-LOTO-GOCandOWLOTO-Premier_8.html","attributes":{"data-id":"id_2001924"},"menu":{"hasChildren":false},"tocID":"id_2001924-d46e221071","topics":[]},{"title":"Removing the host computer <span class=\"ph\">- Dell T5810<\/span>","shortdesc":"<p class=\"shortdesc\">Remove the host computer from the Global Operator Cabinet (GOC) when upgrading the system.<\/p>","href":"t_RemovingTheHostComputer-DellT5810_5.html","attributes":{"data-id":"id_2001773"},"menu":{"hasChildren":false},"tocID":"id_2001773-d46e221175","topics":[]},{"title":"Removing the DVD drive from the host computer<span class=\"ph\"> - Dell T5810<\/span>","shortdesc":"<p class=\"shortdesc\">Remove the DVD drive from the host computer.<\/p>","href":"t_RemovingTheDVDDrive.html","attributes":{"data-id":"id_2007386"},"menu":{"hasChildren":false},"tocID":"id_2007386-d46e221281","topics":[]},{"title":"Installing the DVD drive in the host computer<span class=\"ph\"> - Dell T5810<\/span>","shortdesc":"<p class=\"shortdesc\">Install the DVD drive in the host computer.<\/p>","href":"t_InstallingTheDVDDrive.html","attributes":{"data-id":"id_2007387"},"menu":{"hasChildren":false},"tocID":"id_2007387-d46e221387","topics":[]},{"title":"Installing the host computer <span class=\"ph\">- Dell T5810<\/span>","shortdesc":"<p class=\"shortdesc\">Install the host computer in the Global Operator Cabinet (GOC) after it has been serviced or replaced.<\/p>","href":"t_InstallingTheHostComputer-DellT5810_5.html","attributes":{"data-id":"id_2001778"},"menu":{"hasChildren":false},"tocID":"id_2001778-d46e221493","topics":[]},{"title":"Removing LOTO - Global Operator Cabinet (GOC) and operator workspace","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the GOC and operator workspace before restoring power to these items.<\/p>","href":"t_Removing-LOTO-GOCandOW-Premier_8.html","attributes":{"data-id":"id_2001925"},"menu":{"hasChildren":false},"tocID":"id_2001925-d46e221599","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_67.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e221703","topics":[]},{"title":"Finalizing DVD drive replacement on the host computer","shortdesc":"<p class=\"shortdesc\">Follow this procedure to finalize a DVD drive replacement.<\/p>","href":"t_FinalizingDVDDriveReplacement.html","attributes":{"data-id":"id_2007452"},"menu":{"hasChildren":false},"tocID":"id_2007452-d46e221807","topics":[]}]});